def page_ranges(db, prior_pages):
    """Pack existing rows and retain a full prior page as the stable boundary."""
    ids = [row[0] for row in db.execute('SELECT id FROM events ORDER BY id LIMIT ?', (MAX_EVENTS + 1,))]
    need(len(ids) <= MAX_EVENTS, 'event_retention_limit')
    positions = {ident: offset for offset, ident in enumerate(ids)}
    anchor = 0
    for low, high in sorted(prior_pages):
        position = positions.get(low)
        if position is None:
            continue
        if position >= PAGE_SIZE:
            break
        end = position + PAGE_SIZE - 1
        if end < len(ids) and ids[end] == high:
            anchor = position
            break
    ranges = []
    if anchor:
        ranges.append((ids[0], ids[anchor - 1]))
    for offset in range(anchor, len(ids), PAGE_SIZE):
        end = min(offset + PAGE_SIZE, len(ids)) - 1
        ranges.append((ids[offset], ids[end]))
    return ranges

